    76		const widgetState = isStructuredObject(globals.widgetState)
    77			? globals.widgetState
    78			: {};
    79		const privateContent = isStructuredObject(widgetState.privateContent)
    80			? widgetState.privateContent
    81			: {};
    82		const nextWidgetState = {
    83			...widgetState,
    84			privateContent: {
    85				...privateContent,
    86				[LOBU_VIEW_SNAPSHOT_KEY]: {
    87					version: LOBU_VIEW_SNAPSHOT_VERSION,
    88					data: displaySafeSnapshotData(data),
    89				},
    90			},
    91		};
    92	
    93		try {
    94			const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
    95			if (isStructuredObject(result) && typeof result.catch === "function") {
    96				void Reflect.apply(result.catch, result, [() => {}]);
    97			}
    98			return true;
    99		} catch {
   100			return false;
   101		}
   102	}
   103	
   104	/**
   105	 * Read ChatGPT's compatibility globals without making them a dependency of the
   106	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
   107	 * cards, including after the standard tool-result notification has already
   108	 * happened in an earlier page lifetime.
   109	 */
   110	export function readOpenAiCompatSnapshot<T>(
   111		globals: unknown,
   112	): OpenAiCompatSnapshot<T> {
   113		if (!isStructuredObject(globals)) {
   114			return { data: undefined, approvalCapability: undefined };
   115		}
   116	
   117		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
   118		const hasFullToolResult =
   119			hasToolOutput &&
   120			isStructuredObject(globals.toolOutput) &&
   121			Object.hasOwn(globals.toolOutput, "structuredContent");
   122		const outputData = hasToolOutput
   123			? dataFromToolOutput<T>(globals.toolOutput)
   124			: dataFromWidgetState<T>(globals.widgetState);
   125		const hasToolResponseMetadata = Object.hasOwn(
   126			globals,
   127			"toolResponseMetadata",
   128		);
   129		const metadata = isStructuredObject(globals.toolResponseMetadata)
   130			? globals.toolResponseMetadata
   131			: null;
   132		const approvalCapability = hasToolResponseMetadata
   133			? metadata
   134				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
   135					approvalCapabilityFromResult(metadata.call_tool_result))
   136				: null
   137			: hasFullToolResult
   138				? approvalCapabilityFromResult(globals.toolOutput)
   139				: undefined;
   140		const data =
   141			hasToolOutput && approvalCapability === null
   142				? displaySafeSnapshotData(outputData)
   143				: outputData;
   144	
   145		return { data, approvalCapability };
   146	}

