257	export const RestoreMcpAppResultSchema = Type.Object({
258		tool_call_id: Type.Optional(
259			Type.Union([
260				Type.String({ minLength: 1, maxLength: TOOL_CALL_ID_MAX_LENGTH }),
261				Type.Number(),
262			]),
263		),
264		snapshot_capability: Type.Optional(
265			Type.String({ minLength: 1, maxLength: TOOL_CALL_ID_MAX_LENGTH }),
266		),
267		tool_name: Type.Optional(
268			Type.String({ minLength: 1, maxLength: TOOL_NAME_MAX_LENGTH }),
269		),
270	});
271	
272	export const RestoreMcpAppResultOutputSchema = Type.Object({
273		found: Type.Boolean(),
274		tool_name: Type.Optional(Type.String()),
275		data: Type.Optional(Type.Record(Type.String(), Type.Unknown())),
276		view_state: Type.Record(
277			Type.String(),
278			Type.Union([Type.Boolean(), Type.Number(), Type.String()]),
279		),
280	});
281	
282	async function restoreMcpAppResultImpl(
283		args: {
284			tool_call_id?: string | number;
285			snapshot_capability?: string;
286			tool_name?: string;
287		},
288		_env: Env,
289		ctx: ToolContext,
290	) {
291		const sql = getDb();
292		const identity =
293			args.tool_call_id === undefined
294				? null
295				: snapshotIdentity(ctx, args.tool_call_id);
296		let row: SnapshotRow | undefined;
297		if (identity) {
298			[row] = await sql<SnapshotRow>`
299				SELECT body, tool_name
300				FROM public.mcp_app_result_snapshots
301				WHERE organization_id = ${identity.organizationId}
302					AND client_id = ${identity.clientId}
303					AND user_id = ${identity.userId}
304					AND conversation_key = ${identity.conversationKey}
305					AND tool_call_key = ${identity.toolCallKey}
306					AND expires_at > now()
307			`;
308		}
309	
310		const capabilityIdentity = snapshotIdentity(ctx, args.snapshot_capability);
311		if (!row && capabilityIdentity) {
312			const candidates = await sql<SnapshotLookupRow>`
313				SELECT body, tool_name, tool_call_key
314				FROM public.mcp_app_result_snapshots
315				WHERE organization_id = ${capabilityIdentity.organizationId}
316					AND client_id = ${capabilityIdentity.clientId}
317					AND user_id = ${capabilityIdentity.userId}
318					AND conversation_key = ${capabilityIdentity.conversationKey}
319					AND expires_at > now()
320				ORDER BY updated_at DESC, tool_call_key
321				LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
322			`;
323			row = candidates.find((candidate) => {
324				const snapshot = parseSnapshot(candidate.body);
325				return snapshot?.bindingKey === capabilityIdentity.toolCallKey;
326			});
327		}
328		if (!row || (args.tool_name && row.tool_name !== args.tool_name))
329			return { found: false, view_state: {} };
330		const snapshot = parseSnapshot(row.body);
331		if (!snapshot || snapshot.toolName !== row.tool_name) {
332			logger.warn(
333				{ toolName: row.tool_name },
334				"Discarded unreadable MCP App result snapshot",
335			);
336			return { found: false, view_state: {} };
337		}
338		return {
339			found: true,
340			tool_name: snapshot.toolName,
341			data: snapshot.data,
342			view_state: snapshot.viewState,
343		};
344	}
345	
346	export const restoreMcpAppResult = withValidatedArgs(
347		"restore_lobu_app_result",
348		RestoreMcpAppResultSchema,
349		restoreMcpAppResultImpl,
350	);
351	
352	export const SaveMcpAppStateSchema = Type.Object({
353		tool_call_id: Type.Optional(
354			Type.Union([
355				Type.String({ minLength: 1, maxLength: TOOL_CALL_ID_MAX_LENGTH }),
356				Type.Number(),
357			]),
358		),
359		snapshot_capability: Type.Optional(
360			Type.String({ minLength: 1, maxLength: TOOL_CALL_ID_MAX_LENGTH }),
361		),
362		tool_name: Type.Optional(
363			Type.String({ minLength: 1, maxLength: TOOL_NAME_MAX_LENGTH }),
364		),
365		view_state: Type.Record(Type.String(), Type.Unknown()),
366	});
367	
368	export const SaveMcpAppStateOutputSchema = Type.Object({ saved: Type.Boolean() });
369	
370	async function saveMcpAppStateImpl(
371		args: {
372			tool_call_id?: string | number;
373			snapshot_capability?: string;
374			tool_name?: string;
375			view_state: UnknownRecord;
376		},
377		_env: Env,
378		ctx: ToolContext,
379	) {
380		const identity =
381			args.tool_call_id === undefined
382				? null
383				: snapshotIdentity(ctx, args.tool_call_id);
384		const viewState = boundedMcpAppViewState(args.view_state);
385		const sql = getDb();
386		const bindingIdentity = snapshotIdentity(
387			ctx,
388			// Some hosts preserve their own request metadata but intentionally strip
389			// app-supplied metadata. This private app-only argument keeps the one-time
390			// capability end to end; metadata remains supported for standard hosts.
391			args.snapshot_capability ?? ctx.mcpAppSnapshotCapability,
392		);
393		if (!identity && !bindingIdentity) return { saved: false };
394		if (!identity && bindingIdentity) {
395			try {
396				return await sql.begin(async (tx) => {
397					const candidates = await tx<SnapshotLookupRow>`
398						SELECT body, tool_name, tool_call_key
399						FROM public.mcp_app_result_snapshots
400						WHERE organization_id = ${bindingIdentity.organizationId}
401							AND client_id = ${bindingIdentity.clientId}
402							AND user_id = ${bindingIdentity.userId}
403							AND conversation_key = ${bindingIdentity.conversationKey}
404							AND expires_at > now()
405						ORDER BY updated_at DESC, tool_call_key
406						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
407						FOR UPDATE
408					`;
409					const row = candidates.find((candidate) => {
410						const snapshot = parseSnapshot(candidate.body);
411						return snapshot?.bindingKey === bindingIdentity.toolCallKey;
412					});
413					if (!row || (args.tool_name && row.tool_name !== args.tool_name))
414						return { saved: false };
415					const snapshot = parseSnapshot(row.body);
416					if (!snapshot || snapshot.toolName !== row.tool_name)
417						return { saved: false };
418					const serialized = serializeSnapshot({ ...snapshot, viewState });
419					if (!serialized) return { saved: false };
420					const updated = await tx`
421						UPDATE public.mcp_app_result_snapshots
422						SET tool_call_key = ${bindingIdentity.toolCallKey},
423							body = ${serialized.body},
424							plaintext_bytes = ${serialized.plaintextBytes},
425							updated_at = now()
426						WHERE organization_id = ${bindingIdentity.organizationId}
427							AND client_id = ${bindingIdentity.clientId}
428							AND user_id = ${bindingIdentity.userId}
429							AND conversation_key = ${bindingIdentity.conversationKey}
430							AND tool_call_key = ${row.tool_call_key}
431					`;
