482	    throw new ToolUserError('The MCP App approval capability is invalid or expired.', 403);
483	  }
484	}
485	
486	async function findApprovalRow(
487	  runId: number,
488	  env: Env,
489	  ctx: ToolContext
490	): Promise<ApprovalContentItem> {
491	  // Reuse the canonical knowledge read so connection visibility, public-org
492	  // rules, caller identity, and MCP scope checks cannot drift from the event
493	  // surface. A direct current_event_records query here would be tenant-fenced
494	  // but could bypass a private connection's ACL.
495	  const result = await getContent(
496	    { run_ids: [runId], limit: 50, sort_by: 'date', sort_order: 'desc' },
497	    env,
498	    ctx
499	  );
500	  const row = result.content.find((item) => isApprovalContentItem(item, runId));
501	  if (!row) throw new ToolUserError(`Approval run ${runId} was not found`, 404);
502	  return row;
503	}
504	
505	async function buildApprovalView(runId: number, env: Env, ctx: ToolContext): Promise<LobuView> {
506	  const row = await findApprovalRow(runId, env, ctx);
507	
508	  const status = row.interaction_status ?? 'pending';
509	  const baseTitle = displayValue(row.title ?? `Approval run ${runId}`, TITLE_MAX_LENGTH).replace(
510	    /\s+—\s+pending approval$/i,
511	    ''
512	  );
513	  const actions: LobuView['actions'] = [];
514	  if (status === 'pending') {
515	    const { ownerSlug, baseUrl } = await getOrgUrlContext(ctx);
516	    const href = buildResourcePermalink(ownerSlug, { kind: 'run', runId }, baseUrl);
517	    if (!href || href.length > ACTION_HREF_MAX_LENGTH || !/^https?:\/\//i.test(href)) {
518	      throw new ToolUserError('The Lobu review link is unavailable for this workspace.', 500);
519	    }
520	    const appCanResolve = canIssueApprovalCapability(row, status, ctx);
521	    if (appCanResolve) {
522	      actions.push(
523	        {
524	          id: 'approve',
525	          label: 'Approve',
526	          variant: 'primary',
527	          icon: 'check',
528	          resolvedLabel: 'Approved.',
529	          ...(row.interaction_input_schema ? { submitFormAs: 'input' as const } : {}),
530	          tool: 'resolve_lobu_approval',
531	          args: { run_id: runId, decision: 'approve' },
532	        },
533	        {
534	          id: 'reject',
535	          label: 'Reject',
536	          variant: 'destructive',
537	          icon: 'x',
538	          confirm: true,
539	          confirmPrompt: 'Reject this pending action?',
540	          resolvedLabel: 'Rejected.',
541	          tool: 'resolve_lobu_approval',
542	          args: { run_id: runId, decision: 'reject' },
543	        }
544	      );
545	    }
546	    actions.push({
547	      id: 'review',
548	      label: 'Open in Lobu',
549	      variant: appCanResolve ? 'outline' : 'primary',
550	      icon: 'external',
551	      terminal: false,
552	      href,
553	    });
554	  }
555	
556	  const view: LobuView = {
557	    version: 1,
558	    title: truncate(
559	      status === 'pending' ? baseTitle : `${baseTitle} · ${status}`,
560	      TITLE_MAX_LENGTH
561	    ),
562	    tone: status === 'pending' ? 'warning' : 'default',
563	    blocks: approvalBlocks({
564	      content: row.payload_text,
565	      interaction_input_schema: row.interaction_input_schema,
566	      interaction_input: row.interaction_input,
567	      metadata: row.metadata,
568	    }),
569	    actions,
570	  };
571	  if (canIssueApprovalCapability(row, status, ctx)) {
572	    return attachMcpResultMeta(view, {
573	      'lobu/approval-capability': issueApprovalCapability(row, ctx),
574	    });
575	  }
576	  return view;
577	}
578	
579	const renderLobuViewImpl = async (
580	  args: RenderLobuViewArgs,
581	  env: Env,
582	  ctx: ToolContext
583	): Promise<LobuView> => {
584	  if (args.action === 'review_approval') return buildApprovalView(args.run_id, env, ctx);
585	  return {
586	    version: 1,
587	    ...(args.title ? { title: displayValue(args.title, TITLE_MAX_LENGTH) } : {}),
588	    ...(args.tone ? { tone: args.tone } : {}),
589	    blocks: sanitizeBlocks(args.blocks),
590	    actions: [],
591	  };
592	};
593	
594	export const renderLobuView = withValidatedArgs(
595	  'render_lobu_view',
596	  RenderLobuViewSchema,
597	  renderLobuViewImpl
598	);
599	
600	type ResolveLobuApprovalArgs = Static<typeof ResolveLobuApprovalSchema>;
601	
602	const resolveLobuApprovalImpl = async (
603	  args: ResolveLobuApprovalArgs,
604	  env: Env,
605	  ctx: ToolContext
606	): Promise<LobuView> => {
607	  const capability = readApprovalCapability(ctx.mcpAppApprovalCapability);
608	  if (
609	    capability.runId !== args.run_id ||
610	    ctx.mcpAppsSupported !== true ||
611	    capability.organizationId !== ctx.organizationId ||
612	    capability.userId !== ctx.userId ||
613	    capability.clientId !== ctx.clientId ||
614	    capability.sessionId !== ctx.mcpSessionId ||
615	    capability.expiresAt <= Date.now()
616	  ) {
617	    throw new ToolUserError('The MCP App approval capability is stale or does not match.', 403);
618	  }
619	
620	  const current = await findApprovalRow(args.run_id, env, ctx);
621	  if (current.interaction_status !== 'pending' || current.id !== capability.eventId) {
622	    throw new ToolUserError('This approval capability is stale; the run is no longer pending.', 409);
623	  }
624	  if (belongsToApprovalWindow(current)) {
625	    throw new ToolUserError('Batched proposals must be reviewed in Lobu.', 409);
626	  }
627	
628	  // The encrypted capability proves a signed-in OAuth user deliberately used
629	  // this app surface. The canonical approval handler still performs its own
630	  // membership and run-owner/admin authority checks; clear only the non-human
631	  // transport identities after the capability has been fully revalidated.
632	  const humanContext: ToolContext = {
633	    ...ctx,
634	    agentId: null,
635	    clientId: null,
636	    mcpSessionId: null,
637	    mcpAppApprovalCapability: null,
638	    mcpAppSnapshotCapability: null,
639	  };
640	  const result = await manageOperations(
641	    args.decision === 'approve'
642	      ? { action: 'approve', run_id: args.run_id, ...(args.input ? { input: args.input } : {}) }
643	      : { action: 'reject', run_id: args.run_id, ...(args.reason ? { reason: args.reason } : {}) },
644	    env,
645	    humanContext
646	  );
647	  if ('error' in result && typeof result.error === 'string') {
648	    throw new ToolUserError(result.error, 409);
649	  }
650	  return buildApprovalView(args.run_id, env, ctx);
651	};
652	
653	export const resolveLobuApproval = withValidatedArgs(
654	  'resolve_lobu_approval',
655	  ResolveLobuApprovalSchema,
656	  resolveLobuApprovalImpl
657	);

